create table password_reset_token (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, token_id bigint generated by default as identity, used_at timestamp(6) with time zone, user_id bigint not null, token_hash varchar(64) not null unique, primary key (token_id));
create table pet (age_months integer not null, created_at timestamp(6) with time zone not null, pet_id bigint generated by default as identity, shelter_id bigint not null, updated_at timestamp(6) with time zone not null, sex varchar(10) not null check ((sex in ('MALE','FEMALE'))), size varchar(10) not null check ((size in ('SMALL','MEDIUM','LARGE'))), species varchar(10) not null check ((species in ('DOG','CAT','OTHER'))), moderation_status varchar(20) not null check ((moderation_status in ('ACTIVE','SUSPENDED'))), status varchar(20) not null check ((status in ('AVAILABLE','ADOPTED','ARCHIVED'))), vaccination_status varchar(30) not null check ((vaccination_status in ('VACCINATED','PARTIALLY_VACCINATED','NOT_VACCINATED','UNKNOWN'))), breed varchar(100) not null, name varchar(100) not null, description varchar(1000), primary key (pet_id));
create table shelter (latitude numeric(9,6), longitude numeric(9,6), created_at timestamp(6) with time zone not null, shelter_id bigint generated by default as identity, user_id bigint not null unique, verified_at timestamp(6) with time zone, verified_by bigint, address varchar(255) not null, contact_number varchar(255), description TEXT, organization_name varchar(255) not null, organization_type varchar(255) not null check ((organization_type in ('SHELTER','RESCUER'))), rejection_reason varchar(255), verification_status varchar(255) not null check ((verification_status in ('PENDING','VERIFIED','REJECTED'))), primary key (shelter_id));
create table user_account (failed_login_count integer not null, created_at timestamp(6) with time zone not null, locked_until timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, user_id bigint generated by default as identity, account_status varchar(255) not null check ((account_status in ('ACTIVE','SUSPENDED'))), email varchar(255) not null unique, first_name varchar(255), last_name varchar(255), password_hash varchar(255) not null, phone_number varchar(255), role varchar(255) not null check ((role in ('ADOPTER','SHELTER','ADMIN'))), primary key (user_id));
alter table if exists password_reset_token add constraint FKns9q9f0f318uaoxiqn6lka9ux foreign key (user_id) references user_account;
alter table if exists pet add constraint FKdujrkamkv5tvd3sgqkpu7mwsi foreign key (shelter_id) references shelter;
alter table if exists shelter add constraint FKc48oe2x3b80dadriy94wt6g4n foreign key (user_id) references user_account;
alter table if exists shelter add constraint FKa09milpamnaln9iphdst4g7vd foreign key (verified_by) references user_account;
